import pytest

from tests.pdf_helpers import make_pdf

TXT_DOC = (
    "Project Orion runs on FastAPI. The backend listens on port 8000. "
    "Answers are generated by Groq's Llama model."
)


def _ingest_text(client, name="orion.txt", text=TXT_DOC):
    return client.post("/documents/text", json={"name": name, "text": text})


def test_health(client):
    response = client.get("/health")
    assert response.status_code == 200
    assert response.json() == {"status": "ok"}


def test_ingest_text_and_list(client):
    response = _ingest_text(client)
    assert response.status_code == 200
    body = response.json()
    assert body["name"] == "orion.txt"
    assert body["chunks"] >= 1

    docs = client.get("/documents").json()
    assert len(docs) == 1
    assert docs[0]["chunks"] == body["chunks"]


def test_ingest_markdown(client):
    response = _ingest_text(client, name="notes.md", text="# Notes\n\nThe launch codename is Aquila.")
    assert response.status_code == 200


def test_ingest_pdf(client, fake_llm):
    response = client.post(
        "/documents",
        files={"file": ("handbook.pdf", make_pdf("The office espresso machine is broken."), "application/pdf")},
    )
    assert response.status_code == 200
    assert response.json()["chunks"] >= 1

    answer = client.post("/ask", json={"question": "What is wrong with the espresso machine?"})
    assert answer.status_code == 200
    assert answer.json()["grounded"] is True


def test_unsupported_file_type_rejected(client):
    response = client.post(
        "/documents",
        files={"file": ("malware.exe", b"MZ", "application/octet-stream")},
    )
    assert response.status_code == 400
    assert "Unsupported file type" in response.json()["detail"]


def test_empty_document_rejected(client):
    response = _ingest_text(client, text="   \n\n  ")
    assert response.status_code == 400


def test_answerable_question_with_sources(client, fake_llm):
    _ingest_text(client)
    response = client.post("/ask", json={"question": "What port does the backend use?"})
    assert response.status_code == 200
    body = response.json()
    assert body["grounded"] is True
    assert "Mercury" in body["answer"]  # from the fake LLM
    assert fake_llm.chat.completions.calls == 1
    assert body["sources"][0]["document"] == "orion.txt"
    assert "port 8000" in body["sources"][0]["excerpt"]


def test_unanswerable_question_never_calls_llm(client, monkeypatch):
    _ingest_text(client)

    def explode(settings):
        raise AssertionError("LLM must not be called without evidence")

    monkeypatch.setattr("app.rag.get_llm", explode)
    response = client.post("/ask", json={"question": "What is the CEO's shoe size?"})
    assert response.status_code == 200
    body = response.json()
    assert body["grounded"] is False
    assert body["sources"] == []
    assert "unavailable" in body["answer"].lower()


def test_ask_before_any_ingestion(client, monkeypatch):
    monkeypatch.setattr("app.rag.get_llm", lambda s: (_ for _ in ()).throw(AssertionError()))
    response = client.post("/ask", json={"question": "Anything at all?"})
    assert response.status_code == 200
    assert response.json()["grounded"] is False


def test_empty_question_rejected(client):
    response = client.post("/ask", json={"question": ""})
    assert response.status_code == 422


def test_llm_failure_returns_502(client, monkeypatch):
    _ingest_text(client)

    class Boom:
        class chat:
            class completions:
                @staticmethod
                def create(**kwargs):
                    raise RuntimeError("Groq unavailable")

    monkeypatch.setattr("app.rag.get_llm", lambda s: Boom())
    response = client.post("/ask", json={"question": "What port does the backend use?"})
    assert response.status_code == 502
    assert "LLM request failed" in response.json()["detail"]


def test_delete_document_then_unanswerable(client, fake_llm):
    body = _ingest_text(client).json()
    assert client.delete(f"/documents/{body['doc_id']}").status_code == 200
    assert client.delete(f"/documents/{body['doc_id']}").status_code == 404

    response = client.post("/ask", json={"question": "What port does the backend use?"})
    assert response.json()["grounded"] is False
    assert fake_llm.chat.completions.calls == 0


def test_multi_document_multi_evidence(client, fake_llm):
    _ingest_text(client, name="infra.txt", text="The Orion backend runs on port 8000 inside Docker containers.")
    _ingest_text(client, name="model.txt", text="Orion generates answers using the Llama model via the Groq API.")

    response = client.post(
        "/ask",
        json={
            "question": "How does Orion run inside Docker, and how does Orion generate answers via Groq?"
        },
    )
    body = response.json()
    assert body["grounded"] is True
    assert len(body["sources"]) >= 2
    names = {s["document"] for s in body["sources"]}
    assert names == {"infra.txt", "model.txt"}
